package dominoes

// Domino represents a domino with two halves.
type Domino [2]int

// MakeChain returns a chain of dominoes in which the dots on one half of a
// stone match the dots on the neighboring half of an adjacent stone, and the
// dots on the two halves without a neighbor (the first and last stone) match
// each other. ok is false if no such chain exists.
func MakeChain(input []Domino) ([]Domino, bool) {
	used := make([]bool, len(input))
	chain := make([]Domino, 0, len(input))
	return find(input, used, chain)
}

// find tries to extend chain with the remaining (unused) dominoes so that the
// open ends match. It returns the completed chain and whether it was found.
func find(input []Domino, used []bool, chain []Domino) ([]Domino, bool) {
	if len(chain) == len(input) {
		if len(chain) == 0 {
			return chain, true
		}
		return chain, chain[0][0] == chain[len(chain)-1][1]
	}

	if len(chain) == 0 {
		// Any domino can start the chain.
		for i, d := range input {
			used[i] = true
			if c, ok := find(input, used, append(chain, d)); ok {
				return c, true
			}
			used[i] = false
		}
		return nil, false
	}

	tail := chain[len(chain)-1][1]
	for i, d := range input {
		if used[i] {
			continue
		}
		if d[0] == tail {
			used[i] = true
			if c, ok := find(input, used, append(chain, d)); ok {
				return c, true
			}
			used[i] = false
		}
		if d[1] == tail && d[1] != d[0] {
			used[i] = true
			if c, ok := find(input, used, append(chain, Domino{d[1], d[0]})); ok {
				return c, true
			}
			used[i] = false
		}
	}
	return nil, false
}
